#!/usr/bin/env python3
"""Imports an animation generated by SpriteCook (a spritesheet: frames side by side) for a fighter.

    python3 scripts/import_sheet.py SHEET.png FIGHTER ANIM --source SOURCE.png --placement X Y K [--loop] [--impact N]

- SHEET.png: the spritesheet SpriteCook returns (raw_url / spritesheet_url), square frames side by side;
- FIGHTER: the fighter's name (art/fighters/FIGHTER.json gives its height on the picture);
- ANIM: idle, attack... (see kSheetNames in src/game/fighter_art.cpp);
- SOURCE.png and --placement: the sprite SpriteCook animated (at most 256x256) and how the fighter's picture was
  put into it: picture pixel (x, y) -> source pixel (X + x * K, Y + y * K);
- --loop: a looping animation (idle), played at 8 frames per second;
- --impact N: for a blow, the frame (from 0) where it lands — the game holds it while the move's hitbox is out and
  spreads the frames before and after it over the move's wind-up and recovery.

The frames are matched to the source by their bounding box (SpriteCook re-frames the sprite with a margin), so the
fighter's feet and size are known in the frames. Writes assets/sprites/FIGHTER_ANIM.png and its line in
assets/sprites/sheets.txt: "sheet FIGHTER ANIM frames frame_w frame_h anchor_x anchor_y px_per_height loop impact".
"""
import argparse
import json
import os

from PIL import Image


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("sheet")
    ap.add_argument("fighter")
    ap.add_argument("anim")
    ap.add_argument("--source", required=True)
    ap.add_argument("--placement", type=float, nargs=3, required=True, metavar=("X", "Y", "K"))
    ap.add_argument("--loop", action="store_true")
    ap.add_argument("--impact", type=int, default=-1)
    a = ap.parse_args()

    root = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
    spec = json.load(open(os.path.join(root, "art", "fighters", f"{a.fighter}.json")))
    X, Y, K = a.placement
    # The fighter's anchor (the hips' x on the ground line) and height on the source sprite.
    anchor_src = (X + spec["joints"]["hips"][0] * K, Y + spec["ground"] * K)
    height_src = (spec["ground"] - spec["top"]) * K

    sheet = Image.open(a.sheet).convert("RGBA")
    fh = sheet.height
    fw = fh
    frames = sheet.width // fw
    src_box = Image.open(a.source).convert("RGBA").getbbox()
    f0_box = sheet.crop((0, 0, fw, fh)).getbbox()
    s = (f0_box[3] - f0_box[1]) / max(1, src_box[3] - src_box[1])
    ax = f0_box[0] + (anchor_src[0] - src_box[0]) * s
    ay = f0_box[3] - (src_box[3] - anchor_src[1]) * s
    px_per_h = height_src * s

    out_dir = os.path.join(root, "assets", "sprites")
    os.makedirs(out_dir, exist_ok=True)
    sheet.save(os.path.join(out_dir, f"{a.fighter}_{a.anim}.png"), optimize=True)
    index = os.path.join(out_dir, "sheets.txt")
    lines = []
    if os.path.exists(index):
        lines = [l for l in open(index).read().splitlines()
                 if l.strip() and not l.startswith(f"sheet {a.fighter} {a.anim} ")]
    if not lines or not lines[0].startswith("#"):
        lines.insert(0, "# Generated by scripts/import_sheet.py: "
                        "sheet fighter anim frames frame_w frame_h anchor_x anchor_y px_per_height loop impact")
    lines.append(f"sheet {a.fighter} {a.anim} {frames} {fw} {fh} {ax:.1f} {ay:.1f} {px_per_h:.1f} {1 if a.loop else 0} "
                 f"{a.impact if 0 <= a.impact < frames else -1}")
    open(index, "w").write("\n".join(lines) + "\n")
    print(f"{a.fighter} {a.anim}: {frames} frames of {fw}x{fh}, anchor ({ax:.1f}, {ay:.1f}), "
          f"{px_per_h:.1f} px per fighter height (frame/source scale {s:.3f})")


if __name__ == "__main__":
    main()
